#include "game.h"
#include <stdio.h>
#include <string.h>
void Game::setPixel(int x,int y,Uint8 r,Uint8 g,Uint8 b){ if(!screen) return; if(x<0||y<0||x>=screen->w||y>=screen->h) return; Uint32* p=(Uint32*)screen->pixels; p[y*screen->w+x]=SDL_MapRGB(screen->format,r,g,b); }
void Game::fillRect(int x,int y,int w,int h,Uint8 r,Uint8 g,Uint8 b){ SDL_Rect rc={x,y,w,h}; SDL_FillRect(screen,&rc,SDL_MapRGB(screen->format,r,g,b)); }
void Game::drawFilledCircle(int cx,int cy,int rad,Uint8 r,Uint8 g,Uint8 b){ if(rad<=0) return; for(int y=-rad;y<=rad;y++) for(int x=-rad;x<=rad;x++) if(x*x+y*y<=rad*rad) setPixel(cx+x,cy+y,r,g,b); }
static const unsigned char F[37][5]={
{0x7E,0x09,0x09,0x09,0x7E},{0x7F,0x49,0x49,0x49,0x36},{0x3E,0x41,0x41,0x41,0x22},{0x7F,0x41,0x41,0x22,0x1C},{0x7F,0x49,0x49,0x49,0x41},{0x7F,0x09,0x09,0x09,0x01},{0x3E,0x41,0x49,0x49,0x7A},{0x7F,0x08,0x08,0x08,0x7F},{0x00,0x41,0x7F,0x41,0x00},{0x20,0x40,0x41,0x3F,0x01},{0x7F,0x08,0x14,0x22,0x41},{0x7F,0x40,0x40,0x40,0x40},{0x7F,0x02,0x0C,0x02,0x7F},{0x7F,0x04,0x08,0x10,0x7F},{0x3E,0x41,0x41,0x41,0x3E},{0x7F,0x09,0x09,0x09,0x06},{0x3E,0x41,0x51,0x21,0x5E},{0x7F,0x09,0x19,0x29,0x46},{0x46,0x49,0x49,0x49,0x31},{0x01,0x01,0x7F,0x01,0x01},{0x3F,0x40,0x40,0x40,0x3F},{0x1F,0x20,0x40,0x20,0x1F},{0x3F,0x40,0x38,0x40,0x3F},{0x63,0x14,0x08,0x14,0x63},{0x07,0x08,0x70,0x08,0x07},{0x61,0x51,0x49,0x45,0x43},
{0x3E,0x51,0x49,0x45,0x3E},{0x00,0x42,0x7F,0x40,0x00},{0x42,0x61,0x51,0x49,0x46},{0x21,0x41,0x45,0x4B,0x31},{0x18,0x14,0x12,0x7F,0x10},{0x27,0x45,0x45,0x45,0x39},{0x3C,0x4A,0x49,0x49,0x30},{0x01,0x71,0x09,0x05,0x03},{0x36,0x49,0x49,0x49,0x36},{0x06,0x49,0x49,0x29,0x1E},{0x00,0x00,0x00,0x00,0x00}
};
static int fidx(char c){ if(c>='A'&&c<='Z') return c-'A'; if(c>='a'&&c<='z') return c-'a'; if(c>='0'&&c<='9') return 26+(c-'0'); if(c=='!') return 36; if(c=='?') return 36; if(c==':') return 36; if(c=='.') return 36; return 36; }
void Game::drawChar(int x,int y,char c,int sc,Uint8 r,Uint8 g,Uint8 b){ if(c==' ') return; int id=fidx(c); for(int dy=0;dy<7;dy++) for(int dx=0;dx<5;dx++){ if(F[id][dx]&(1<<(6-dy))){ for(int sy=0;sy<sc;sy++) for(int sx=0;sx<sc;sx++) setPixel(x+dx*sc+sx,y+dy*sc+sy,r,g,b); } } }
int Game::textWidth(const char* t,int sc){ return (int)strlen(t)*6*sc; }
void Game::drawText(const char* t,int x,int y,int sc,Uint8 r,Uint8 g,Uint8 b){ int cx=x; for(int i=0;t[i];i++){ drawChar(cx,y,t[i],sc,r,g,b); cx+=6*sc; } }
void Game::drawTextCentered(const char* t,int y,int sc,Uint8 r,Uint8 g,Uint8 b){ int w=textWidth(t,sc); drawText(t,(screen->w-w)/2,y,sc,r,g,b); }
void Game::drawBackground(){
fillRect(0,0,screen->w,screen->h,20,60,200);
for(int gx=0;gx<screen->w;gx+=70){ for(int y=0;y<screen->h;y++) setPixel(gx,y,35,85,225); }
for(int gy=0;gy<screen->h;gy+=70){ for(int x=0;x<screen->w;x++) setPixel(x,gy,35,85,225); }
}
void Game::drawFood(){ for(int i=0;i<MAX_FOOD;i++){ if(!foods[i].active) continue; Vec2 s=worldToScreen(foods[i].pos.x,foods[i].pos.y); int rr=(int)(foods[i].radius*zoom); drawFilledCircle((int)s.x,(int)s.y,rr+3,foods[i].r/4,foods[i].g/4,foods[i].b/4); drawFilledCircle((int)s.x,(int)s.y,rr,foods[i].r,foods[i].g,foods[i].b); drawFilledCircle((int)s.x-2,(int)s.y-2,rr/3,255,255,255); } }
void Game::drawSnake(Snake &s){ if(!s.alive) return; for(int i=(int)s.body.size()-1;i>=0;i--){ Vec2 sc=worldToScreen(s.body[i].x,s.body[i].y); int rad=(int)(s.radius*zoom); if(rad<2) rad=2; if(i%2==0) drawFilledCircle((int)sc.x,(int)sc.y,rad,s.cr,s.cg,s.cb); else drawFilledCircle((int)sc.x,(int)sc.y,rad,s.cr2,s.cg2,s.cb2); } if(!s.body.empty()){ Vec2 h=worldToScreen(s.body[0].x,s.body[0].y); drawFilledCircle((int)h.x+6,(int)h.y-6,4,255,255,255); drawFilledCircle((int)h.x+6,(int)h.y-6,2,0,0,0); drawText(s.name.c_str(),(int)h.x-20,(int)h.y-32,1,255,255,255); } }
void Game::drawParticles(){ for(int i=0;i<MAX_PARTICLES;i++){ if(!particles[i].active) continue; Vec2 s=worldToScreen(particles[i].pos.x,particles[i].pos.y); drawFilledCircle((int)s.x,(int)s.y,(int)particles[i].size,particles[i].r,particles[i].g,particles[i].b); } }
void Game::drawMinimap(){ int mx=screen->w-270,my=15,mw=250,mh=180; fillRect(mx,my,mw,mh,10,40,160); for(int i=0;i<MAX_FOOD;i++){ if(!foods[i].active) continue; int px=mx+(int)((foods[i].pos.x+WORLD_RADIUS)/(WORLD_RADIUS*2)*mw); int py=my+(int)((foods[i].pos.y+WORLD_RADIUS)/(WORLD_RADIUS*2)*mh); if(px>=mx&&px<mx+mw&&py>=my&&py<my+mh) setPixel(px,py,255,255,255); } for(int i=0;i<MAX_SNAKES;i++){ if(!snakes[i].alive) continue; int px=mx+(int)((snakes[i].body[0].x+WORLD_RADIUS)/(WORLD_RADIUS*2)*mw); int py=my+(int)((snakes[i].body[0].y+WORLD_RADIUS)/(WORLD_RADIUS*2)*mh); drawFilledCircle(px,py,3,snakes[i].cr,snakes[i].cg,snakes[i].cb); } }
void Game::drawRanking(){ int x=screen->w-270,y=205,w=250; fillRect(x,y,w,230,0,0,0); drawText("RANKING",x+10,y+5,2,255,255,0); int show=rankCount<8?rankCount:8; for(int i=0;i<show;i++){ Snake &s=snakes[rankOrder[i]]; bool me=(&s==&snakes[0]); if(me) fillRect(x,y+30+i*22,w,22,0,120,0); char buf[64]; snprintf(buf,sizeof(buf),"%d. %s %d",i+1,s.name.c_str(),(int)s.length); drawText(buf,x+5,y+33+i*22,1,255,255,255); } bool in=false; for(int i=0;i<show;i++) if(rankOrder[i]==0) in=true; if(!in&&snakes[0].alive){ char buf[64]; snprintf(buf,sizeof(buf),"%d. VOCE %d",playerRank,(int)snakes[0].length); fillRect(x,y+30+show*22,w,22,0,120,0); drawText(buf,x+5,y+33+show*22,1,255,255,255); } }
void Game::drawHUD(){ char buf[128]; snprintf(buf,sizeof(buf),"PONTOS: %d TAM: %d POS: %d",snakes[0].score,(int)snakes[0].length,playerRank); drawText(buf,20,20,2,255,255,255); if(snakes[0].boosting) drawText("TURBO!",20,50,2,255,200,0); drawText("ANALOGICO MOVER - X TURBO - CIRCULO SAIR",20,screen->h-30,1,255,255,255); }
void Game::drawMenu(){ drawBackground(); drawTextCentered("SLIPS3",130,7,255,255,255); drawTextCentered("SLITHER DO PS3",260,2,255,255,255); if((frameCount/30)%2==0) drawTextCentered("PRESSIONE START",360,3,255,255,0); drawTextCentered("ANALOGICO PARA MOVER - X PARA TURBO",450,2,255,255,255); char b[64]; snprintf(b,sizeof(b),"MELHOR: %d",bestScore); drawTextCentered(b,500,2,255,200,0); }
void Game::drawDeath(){ fillRect(0,0,screen->w,screen->h,10,10,40); drawTextCentered("VOCE MORREU!",130,5,255,50,50); char b[128]; snprintf(b,sizeof(b),"PONTOS: %d TAM: %d ABATES: %d",deathScore,deathLength,deathKills); drawTextCentered(b,280,2,255,255,255); snprintf(b,sizeof(b),"POSICAO: %d MELHOR: %d",deathRank,bestScore); drawTextCentered(b,330,2,255,255,255); if((frameCount/30)%2==0) drawTextCentered("PRESSIONE START",450,3,255,255,0); }
void Game::render(){ if(!screen) return; if(SDL_MUSTLOCK(screen)) SDL_LockSurface(screen); if(gameState==0) drawMenu(); else if(gameState==2) drawDeath(); else { drawBackground(); drawFood(); for(int i=0;i<MAX_SNAKES;i++) if(snakes[i].alive) drawSnake(snakes[i]); drawParticles(); drawMinimap(); drawRanking(); drawHUD(); } if(SDL_MUSTLOCK(screen)) SDL_UnlockSurface(screen); SDL_Flip(screen); }